sys_script_client.script:
function onLoad() {
    //Type appropriate comment here, and begin script below
//MSSFUNDS-54: Call a script include to check active tasks
    var gaTask = new GlideAjax('x_hsb11_mss_fund_0.MSS_Funds_Client_Utils');
    gaTask.addParam('sysparm_name', 'checkActiveTasks');
    gaTask.addParam('sysparm_caseID', g_form.getUniqueValue());
    gaTask.getXML(callBackFunction);

    function callBackFunction(response) {
        var answer = response.responseXML.documentElement.getAttribute('answer');
        if (answer == 'true')
            g_form.setDisabled('final_check_status', true);//MSSFUNDS-54: Make field read-only
    }

}
